head.script:
// ===== 리턴 값 출력 영역 =====
scwin.btn_clear_onclick = function (e) {
    $p.getComponentById("tbx_return").setValue("");
};

scwin.setReturnValue = function (strValue) {
    var objReturn = $p.getComponentById("tbx_return");
    objReturn.setValue(objReturn.getValue() + strValue);
    objReturn.setValue(objReturn.getValue() + "\n");
};

// ===== 결함 재현 (5.0 vs 6.0 동작 비교) =====

// XHR 의 withCredentials 설정 여부를 기록한다.
//  다운로드 요청은 화면에 남지 않으므로, XMLHttpRequest 의 withCredentials 대입과
//  send() 시점의 값을 가로채 기록한 뒤 곧바로 원복한다. (실제 요청은 그대로 통과)
scwin.gVar = { setCalls : [], atSend : null };

scwin.hookXHR = function () {
    scwin.gVar = { setCalls : [], atSend : null };

    var objDesc = Object.getOwnPropertyDescriptor(XMLHttpRequest.prototype, "withCredentials");
    var fnSend = XMLHttpRequest.prototype.send;

    Object.defineProperty(XMLHttpRequest.prototype, "withCredentials", {
        get : function () { return objDesc.get.call(this); },
        set : function (v) { scwin.gVar.setCalls.push(String(v)); objDesc.set.call(this, v); },
        configurable : true
    });
    XMLHttpRequest.prototype.send = function () {
        if (scwin.gVar.atSend === null) { scwin.gVar.atSend = String(this.withCredentials); }
        return fnSend.apply(this, arguments);
    };

    scwin.gVar.unhook = function () {
        Object.defineProperty(XMLHttpRequest.prototype, "withCredentials", objDesc);
        XMLHttpRequest.prototype.send = fnSend;
    };
};

scwin.download = function (bCred) {
    var objTarget = $p.getComponentById("target1");

    scwin.hookXHR();
    try {
        objTarget.advancedExcelDownload({
            fileName : "withCredentials_" + bCred,
            extension : "xlsx",
            useXHR : "true",
            withCredentials : bCred,
            onSuccessCallback : function () {}
        });
    } finally {
        setTimeout(scwin.gVar.unhook, 3000);
    }

    setTimeout(function () {
        var arrSet = scwin.gVar.setCalls;
        scwin.setReturnValue("=====withCredentials : " + bCred + " 로 호출=====");
        scwin.setReturnValue("    전달 옵션 : { useXHR : 'true', withCredentials : " + bCred + " }");
        scwin.setReturnValue("    XHR.withCredentials 대입 : " + (arrSet.length === 0 ? "없음 (대입 자체가 일어나지 않음)" : arrSet.join(", ")));
        scwin.setReturnValue("    send() 시점의 값 : " + scwin.gVar.atSend);
        scwin.setReturnValue("");
        scwin.setReturnValue("----- 판정 -----");
        if (String(scwin.gVar.atSend) === String(bCred)) {
            scwin.setReturnValue("전달한 withCredentials 값이 XHR 에 그대로 적용되었다");
        } else {
            scwin.setReturnValue("전달한 withCredentials 값이 XHR 에 적용되지 않았다 (요청 시 인증 정보가 전송되지 않음)");
        }
        scwin.setReturnValue("");
    }, 2500);
};

scwin.btn_true_onclick  = function (e) { scwin.download(true); };
scwin.btn_false_onclick = function (e) { scwin.download(false); };
